p='ace/dit/gpu.go'
s=open(p).read()
pairs=[
("""	gemmBigW64                   // the wave64 128x256 build gemmBig replaced; screens only
)""",
"""	gemmBigW64                   // the wave64 128x256 build, for short clips (bigW64Rows)
)

// bigW64Rows is the row count up to which the big projections run on the
// wave64 build (KERNELS.md G8, 2026-09-29): at 375 rows (a 30 s clip) the
// LDS-staged build is 8% slower a forward (130 against 120 ms; its grid is
// 30 workgroups and the per-slab barrier shows), the two tie at 1500, and
// from 3000 rows the LDS build wins by 2.5-3%. The 64x64 rung is never the
// answer (131 ms at 375, 1.2-1.4x slower above).
const bigW64Rows = 1024"""),
("""	// The wave64 build gemmBig replaced, kept for the screen (ACE_DIT_BIG=w64
	// in TestGPUStepTiming).
	gemmBigW64: {shaders.DiTGEMMWG128x256TiledSWZ8, 128, 256, 16, 0},""",
"""	// The wave64 build gemmBig replaced, which still wins up to bigW64Rows.
	gemmBigW64: {shaders.DiTGEMMWG128x256TiledSWZ8, 128, 256, 16, 0},"""),
]
for old,new in pairs:
    assert old in s, old[:60]; s=s.replace(old,new,1)
# the rule inside gemm(): find the func signature line
import re
m=re.search(r"func \(gr \*graph\) gemm\(kernel gemmKernel, ([^)]*)\) error \{\n", s)
assert m, "gemm sig"
sig=m.group(0); print(sig.strip())
params=m.group(1)
# rows param name: the one after bOff
rows=params.split("bOff uint32, ")[1].split(",")[0].split(" ")[0]
print("rows param:", rows)
s=s.replace(sig, sig+"""	if kernel == gemmBig && %s <= bigW64Rows {
		kernel = gemmBigW64
	}
""" % rows, 1)
open(p,'w').write(s)
EOF
go build ./ace/... && go vet ./ace/dit && cd /home/kube/repos/strix-halo-vulkan && S=/tmp/claude-1000/-home-kube-repos-strix-halo-vulkan/52025e37-e99f-41af-81f6-04ea3d9309c8/scratchpad && go test ./ace/dit -run 'TestGPUDiT$|TestGPUStepTiming$' -v -timeout 40m > $S/g8_acedit_final.log 2>&1; echo "exit $?"; grep -E "^(--- |ok|FAIL)|a forward" $S/g8_acedit_final.log

